import base64

with open('logo_small.png', 'rb') as f:
    logo_b64 = base64.b64encode(f.read()).decode('utf-8')

with open('webui.py', 'r') as f:
    content = f.read()

new_img_tag = f'<img src="data:image/png;base64,{logo_b64}" width="60" height="60" alt="拾燕" style="border-radius:14px;">'

content = content.replace(
    '<img src="data:image/png;base64,""60" height="60" alt="拾燕" style="border-radius:14px;">',
    new_img_tag
)

with open('webui.py', 'w') as f:
    f.write(content)

print("修复完成！")
print(f"新logo大小: {len(logo_b64)} 字节")
